"""Emit runtime/include/gen_segments.h from recon/analysis.json."""

from __future__ import annotations

import json
from pathlib import Path
from typing import Any

REPO = Path(__file__).resolve().parents[2]
ANALYSIS = REPO / "recon" / "analysis.json"
OUTPUT = REPO / "runtime" / "include" / "gen_segments.h"

HEADER = """\
/* Generated by tools/hobbit/emit_runtime.py from recon/analysis.json. Do not edit. */
#ifndef GEN_SEGMENTS_H
#define GEN_SEGMENTS_H

#include <stdint.h>

typedef struct {
    const char *name;
    uint32_t vmaddr;
    uint32_t vmsize;
    uint32_t fileoff;
    uint32_t filesize;
    uint32_t initprot;
} guest_segment_t;

static const guest_segment_t GUEST_SEGMENTS[] = {
"""


def render(analysis: dict[str, Any]) -> str:
    lines = [HEADER]
    segments: list[dict[str, Any]] = analysis["segments"]
    for seg in segments:
        lines.append(
            '    {"%s", 0x%x, 0x%x, 0x%x, 0x%x, %d},\n'
            % (
                seg["name"],
                seg["vmaddr"],
                seg["vmsize"],
                seg["fileoff"],
                seg["filesize"],
                seg["initprot"],
            )
        )
    lines.append("};\n\n")
    lines.append(
        "#define GUEST_SEGMENT_COUNT "
        "(sizeof(GUEST_SEGMENTS) / sizeof(GUEST_SEGMENTS[0]))\n\n#endif\n"
    )
    return "".join(lines)


def main() -> None:
    analysis = json.loads(ANALYSIS.read_text())
    OUTPUT.parent.mkdir(parents=True, exist_ok=True)
    OUTPUT.write_text(render(analysis))


if __name__ == "__main__":
    main()
